import{_ as t,o as a,c as n,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy offline records and later teacher services","description":"Historical snapshot preserved November 11, 2026 before the technical-document cleanup.\\nUse the current document for the active design.","frontmatter":{"title":"Chainy offline records and later teacher services","description":"Historical snapshot preserved November 11, 2026 before the technical-document cleanup.\\nUse the current document for the active design.","source":"docs/archive/pre-lesson-collection-2026-11-11/offline-data-plan.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/offline-data-plan.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/offline-data-plan.md"}'),r={name:"content/docs/archive/pre-lesson-collection-2026-11-11/offline-data-plan.md"};function i(s,e,c,d,l,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<div><blockquote><p>Historical snapshot preserved November 11, 2026 before the technical-document cleanup. Use the <a href="/Chainy-Docs/content/docs/offline-data-plan.html">current document</a> for the active design.</p></blockquote><h1 id="chainy-offline-records-and-later-teacher-services">Chainy offline records and later teacher services<a class="header-anchor" href="#chainy-offline-records-and-later-teacher-services" aria-label="Link to this section">​</a></h1><p>Updated November 11, 2026 for the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a> and <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-baseline.html">current baseline</a>. <strong>Development gate: documentation and necessary preparation only until the owner&#39;s explicit FINAL approval.</strong> This plan does not authorize implementing storage, exports, pairing, uploads, or application changes.</p><h2 id="current-offline-gameplay">Current offline gameplay<a class="header-anchor" href="#current-offline-gameplay" aria-label="Link to this section">​</a></h2><p>The complete learning journey runs on the device without an account server, real wallet, public blockchain, cloud model, or teacher connection. SQLite holds isolated local profile progress for Web3 → Blockchain → AI. Each world requires tutorial completion, its 13 ordered encyclopedia entries, and its required five-question review before the next world unlocks. Minigame item/NPC prerequisite steps persist when the player exits or restarts the activity. AI activities are labeled teaching simulations; no real model training or independent AI test result is implied.</p><p>The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/design/database-schema.html#current-progress-contract">database contract</a> defines the records and atomic transitions. Keep lesson collection separate from quiz evidence: first responses, corrected completion, abandonment, and replay have different meanings. An abandoned review restarts all five questions in a new attempt while retaining its earlier partial responses; it does not become a completed score. Recorded entries, finished worlds, or successful corrections do not establish learning gain or school grading.</p><h2 id="separate-workflows">Separate workflows<a class="header-anchor" href="#separate-workflows" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Workflow</th><th>Current boundary</th></tr></thead><tbody><tr><td>Play and save</td><td>Local SQLite and safe checkpoints; no network dependency</td></tr><tr><td>Evidence procedure</td><td>Sean documents approved observation fields, purpose, custodian, access, and retention; actual permissions and results must be supplied</td></tr><tr><td>Export</td><td>Later, only approved logical records; file creation is not proof of receipt, and failure must preserve local data</td></tr><tr><td>File transfer or upload</td><td>Separate destination/receipt and duplicate-detection rules; no selected transport or backend is implied</td></tr><tr><td>Teacher enrollment/dashboard</td><td>Outside the current game; local learner codes and board accounts do not supply teacher authentication</td></tr><tr><td>Content update</td><td>Versioned lesson/quiz content with explicit saved-progress compatibility</td></tr><tr><td>App update</td><td>Named signed build with tested in-place data preservation; separate from content transfer</td></tr></tbody></table><p>Use synthetic records for technical verification. Participant records, identity maps, identifiable photos, credentials, and signing keys stay outside repositories and public issues. A local code identifies a profile on that device; it does not recover data on another phone. If collection/export is later needed, identify attempts so repeated transfer or replay does not inflate evidence totals. Never delete local records just because export was attempted.</p><h2 id="evidence-and-readiness">Evidence and readiness<a class="header-anchor" href="#evidence-and-readiness" aria-label="Link to this section">​</a></h2><p>The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-baseline.html#current-implementation-evidence">November 11 audit</a> found existing local storage and profile/encyclopedia infrastructure. It did not verify this new journey&#39;s persistence or Android readiness; Android Build Support was missing and the attempted installation was cancelled. No new network backend is needed to close those gaps. After FINAL approval, test profile separation, failed-save retry, restart, scene return, quiz abandonment, and compatible app updates against a named build.</p><p>The actual outcome of the November 10 Cryptita Plays session remains unverified in the current baseline. Do not describe its feedback as gameplay acceptance or approved school pilot evidence without the corresponding records. The November 21, 2026 pre-final remains fixed; retain integration, device QA, manuscript, and rehearsal time.</p><h2 id="historical-service-plan">Historical service plan<a class="header-anchor" href="#historical-service-plan" aria-label="Link to this section">​</a></h2><p>Everything below preserves the October 23 plan and November 7 contingency for context. Its economy records and teacher-service proposals are historical and are not requirements or implementation authorization for the current game.</p><p>October 23, 2026. Christian owns storage; Sean authors evidence procedures; Sherwin coordinates arrangements; Miguel owns screens. <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/game-design.html">GDD v2</a> separates gameplay from later services.</p><h3 id="november-10-core">November 10 core<a class="header-anchor" href="#november-10-core" aria-label="Link to this section">​</a></h3><p>Play and save entirely on the device using a clearly labeled local demo profile. SQLite persists quests, journal/encyclopedia progress, inventory, balances, ledger, world restoration, checkpoints and versions. A reward or purchase commits related changes together and can be retried without duplication. A code is not authentication or cross-device recovery.</p><p>Cryptita Plays community beta testing needs a safe, approved observation/evidence process, not an unfinished teacher platform. Sean confirms necessary fields, permitted participants, custodian and restricted destination. A minimal staff export may be used only if needed and tested; do not make a broad collection service block the gameplay core.</p><p>November 7 owner contingency: if no installable core APK exists at the November 9 go/no-go, the November 10 community session is clearly labeled concept/prototype feedback. Such feedback does not demonstrate offline gameplay or local-save acceptance and is not automatically school-approved pilot evidence. The November 21 pre-final remains fixed.</p><h3 id="separate-jobs">Separate jobs<a class="header-anchor" href="#separate-jobs" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Job</th><th>Boundary</th></tr></thead><tbody><tr><td>Offline play/save</td><td>Local SQLite; independent of a nearby teacher after later enrollment</td></tr><tr><td>Enrollment</td><td>Full-product Teacher/Student selection, developer-issued teacher voucher/one online activation, offline student pairing and protected dashboard; later service, not working beta security</td></tr><tr><td>Collection</td><td>Gather approved logical records from personal learner phones; 20–40 phones is a design use case, not proven simultaneous connectivity</td></tr><tr><td>Upload/transfer</td><td>Separately confirm receipt at the approved restricted destination; SQLite does not synchronize itself</td></tr><tr><td>Content update</td><td>Versioned content package; define compatibility and interruption behavior</td></tr><tr><td>App update</td><td>Signed APK with tested in-place data preservation; not a content update or silent-install promise</td></tr></tbody></table><p>Nearby Connections/local Wi-Fi are prototype candidates, not selected or implemented solutions. Do not expose developer credentials, real wallet secrets or identity maps. Game blockchain nodes are simulated records, not learner phones acting as a real blockchain.</p><h3 id="data-handling-and-recovery">Data handling and recovery<a class="header-anchor" href="#data-handling-and-recovery" aria-label="Link to this section">​</a></h3><ul><li>Collect only approved fields; community feedback is not automatically school-approved research.</li><li>Keep identity mapping with the authorized custodian; no participant records or identifiable photos in repositories/issues.</li><li>Define whether evidence means current progress, a playthrough, an answer or a first independent AI test; do not count replay as new independent learning evidence.</li><li>Cancelled/failed export preserves local records. Receipt confirmation is separate from file creation.</li><li>Repeat collection must not inflate totals. Keep profiles separated.</li><li>Test backups, version changes, interrupted saves and in-place updates with synthetic records.</li><li>Never delete local data merely because export was attempted.</li></ul><p>See the <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/design/database-schema.html">database contract</a>, <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/qa-evaluation.html">evaluation plan</a> and <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/kanban-plan-draft.html">November 10 schedule</a>.</p></div>',1)])])}const f=t(r,[["render",i]]);export{u as __pageData,f as default};
